function interactionAt(){
 const p=world.player,ride=journey.interaction,otherVehicle=!!journey.vehicle&&!journey.skating;
 const atMoscowCrew=!otherVehicle&&Math.hypot(p.x-326,p.z-36)<6,atSolCrew=!otherVehicle&&Math.hypot(p.x-515,p.z+25)<7;
 const atFloor=!otherVehicle&&Math.hypot(p.x-DANCE_FLOOR.x,p.z-DANCE_FLOOR.z)<DANCE_FLOOR.radius;
 const atPodium=!otherVehicle&&Math.hypot(p.x-STAGE.x,p.z-STAGE.z)<7;
 if(journey.story.running){
  const step=journey.story.step;
  if(step===8&&!journey.vehicle&&Math.hypot(p.x-STORY_STAGE.x,p.z-STORY_STAGE.z)<7)return{type:'storyFinish',label:'Dance Finish'};
  if(atFloor)return step===6?{type:'storyBattle',label:'Начать сюжетный баттл'}:{type:'floorBattle',label:'Начать баттл · повтори движения'};
  if(ride&&['vehicle','stageBattle','metro'].includes(ride.type))return ride;
  if(atPodium)return{type:'podiumBattle',label:'Баттл на подиуме · повтори связку'};
  return ride&&journey.vehicle?ride:{type:'skate',label:'Встать на скейт'};
 }
 if(journey.artifactQuest.running)return journey.skating?ride:!journey.vehicle?{type:'skate',label:'Встать на скейт'}:ride;
 if(journey.missions.running)return journey.skating?ride:{type:'skate',label:'Встать на скейт'};
 const jam=!otherVehicle&&!skills.race&&!journey.park.active&&!journey.skateChallenge&&!journey.contracts.running&&!journey.crew.running&&!journey.race&&!journey.chase?.running&&jamAt(p);if(jam)return{type:'jamBattle',id:jam.id,label:'Войти в джем',key:'G'};
 if(journey.crew.stage==='train'&&!journey.vehicle&&Math.hypot(p.x-CREW_TRAINER.x,p.z-CREW_TRAINER.z)<4)return{type:'crewTrain',label:'Выучить новое движение',key:'L'};
 if(atSolCrew&&!skills.race&&!journey.park.active&&!journey.skateChallenge)return{type:'crewBattle',label:'Баттл с командой Солнцево',key:'G'};
 if(atMoscowCrew&&!skills.race&&!journey.park.active&&!journey.skateChallenge)return{type:'crewBattle',label:'Баттл с командой Московского',key:'G'};
 if(atFloor&&!skills.race&&!journey.park.active&&!journey.skateChallenge)return{type:'floorBattle',label:'Начать баттл · повтори движения'};
 if(atPodium&&!skills.race&&!journey.park.active&&!journey.skateChallenge){if(ride&&(ride.type==='stageBattle'||ride.type==='final'&&!journey.celebrated))return ride;return{type:'podiumBattle',label:'Баттл на подиуме · повтори связку'};}
 if(journey.skating)return ride;
 if(journey.park.active?.id==='dance'){const target=DANCE_SPOTS[journey.park.active.index];if(Math.hypot(p.x-target.x,p.z-target.z)<3)return{type:'parkDance',label:'Танцуй! ♫'};}
 const park=journey.park.interaction;if(park)return park;
 if(ride)return ride;
 if(!journey.vehicle&&sideGoal==='race'&&!skills.race&&Math.hypot(p.x-RACE.x,p.z-RACE.z)<3)return{type:'race',label:'Начать пеший забег'};
 if(!journey.vehicle){const i=RIVALS.findIndex((r,i)=>Math.hypot(p.x-r.x,p.z-r.z)<4.2&&(world.count>=r.coins||world.won.has(i)));if(i>=0)return{type:'rival',index:i,label:'Дополнительный баттл'};}
 return journey.vehicle?null:{type:'skate',label:'Встать на скейт'};
}
