function moveStick(e){const r=joy.getBoundingClientRect(),origin=stickOrigin||{x:r.left+r.width/2,y:r.top+r.height/2},dx=e.clientX-origin.x,dz=e.clientY-origin.y,radius=Math.max(1,r.width*.36),len=Math.hypot(dx,dz),ratio=len>radius?radius/len:1;Object.assign(touch,stickInput(dx,dz,radius));$('stick').style.transform=`translate(${dx*ratio}px,${dz*ratio}px)`;}
function beginStick(e,floating=false){if(stickPointer!==null||flow.paused||flow.loading||flow.screen!=='roam')return;e.preventDefault();stickPointer=e.pointerId;stickOrigin=floating?{x:e.clientX,y:e.clientY}:null;if(floating){const r=joy.getBoundingClientRect();joy.style.left=(e.clientX-r.width/2)+'px';joy.style.top=(e.clientY-r.height/2)+'px';joy.style.bottom='auto';}joy.classList.add('engaged');(floating?$('moveZone'):joy).setPointerCapture(e.pointerId);moveStick(e);}
function endStick(e){if(e.pointerId!==stickPointer)return;stickPointer=null;stickOrigin=null;touch.x=touch.z=0;joy.classList.remove('engaged');joy.style.left=joy.style.top=joy.style.bottom='';$('stick').style.transform='';}
for(const [surface,floating]of[[joy,false],[$('moveZone'),true]]){surface.addEventListener('pointerdown',e=>beginStick(e,floating));surface.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer){e.preventDefault();moveStick(e);}});for(const type of['pointerup','pointercancel','lostpointercapture'])surface.addEventListener(type,endStick);}
$('world').addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&e.clientX<innerWidth*.45)return;if(flow.screen!=='roam'||flow.paused||flow.loading||drag||(e.button!==undefined&&e.button!==0))return;e.preventDefault();drag={id:e.pointerId,x:e.clientX,y:e.clientY};manualCameraAt=performance.now();$('world').setPointerCapture(e.pointerId);});$('world').addEventListener('pointermove',e=>{if(drag?.id===e.pointerId){e.preventDefault();cameraYaw-=(e.clientX-drag.x)*.006;cameraPitch=Math.max(-.9,Math.min(1.3,cameraPitch+(e.clientY-drag.y)*.003));drag.x=e.clientX;drag.y=e.clientY;manualCameraAt=performance.now();}});for(const type of['pointerup','pointercancel','lostpointercapture'])$('world').addEventListener(type,e=>{if(e.pointerId===drag?.id)drag=null;});
document.querySelectorAll('[data-lane]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press(+b.dataset.lane);});for(const type of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(type,()=>release(+b.dataset.lane));});
window.addEventListener('blur',()=>{if(ACTIVE())pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&ACTIVE())pause();});window.addEventListener('pagehide',save);
function rebuildRenderer(){renderer=new Renderer($('world'));const scenery=staticWorld();playfulWorld(scenery);drawSkateArea(scenery);const partition=splitStatic(scenery);renderer.setStatic(partition.global);renderer.setChunks([...partition.chunks,...cityChunks(),...moskovskyChunks(),...solntsevoChunks(),...capitalChunks(),...streetChunks(),...urbanChunks(),...metroChunks(),...streetEventChunks()]);}
$('world').addEventListener('webglcontextlost',event=>{event.preventDefault();contextLost=true;resetInput();save();$('resume').disabled=true;void pause();toast('Графика временно недоступна. Игра приостановлена.');});
$('world').addEventListener('webglcontextrestored',()=>{try{rebuildRenderer();contextLost=false;applyQuality();$('resume').disabled=false;$('error').classList.add('hidden');toast('Графика восстановлена. Можно продолжить игру.');}catch(e){$('errorMessage').textContent=e.message;$('error').classList.remove('hidden');}});
try{rebuildRenderer();setupLabels();syncMode();applySettings();updateStart();updateMusicHUD();requestAnimationFrame(step);}catch(e){$('errorMessage').textContent=e.message;$('error').classList.remove('hidden');}

function resetMissionCamera(){const p=world.player;cameraYaw=p.yaw;cameraEye=[p.x+Math.sin(p.yaw)*10,p.y+7,p.z+Math.cos(p.yaw)*10];cameraTarget=[p.x,p.y+1.5,p.z];}
async function launchMusicMission(id,dialog='journal'){
 if(flow.screen!=='roam'||flow.loading||musicLoading)return;
 if(journey.story.running||journey.artifactQuest.running){toast('Сначала заверши текущее приключение.');return;}
 if(skills.race||!journey.missions.start(id)){toast('Заверши другое испытание и выйди из машины, чтобы начать миссию.');return;}
 sideGoal=null;resetInput();resetMissionCamera();journeyEvents();await closeModal(dialog);updateHUD();
}
function musicMissionResult(e){$('musicResultTitle').textContent=e.title;$('musicResultStats').textContent='Время: '+e.time.toFixed(1)+' с · '+(journey.missions.definition.styleGoal?'Style Points: '+journey.missions.active.stylePoints+' · комбо: '+journey.missions.active.combos:journey.missions.definition.tokens.length?'Винилы: '+journey.missions.active.collected.size:'Рампы: '+journey.missions.active.ramps.size+' / 3');$('musicResultReward').textContent=e.first?'Награда: +'+e.points+' очков и '+e.coins+' монет.':'Повтор пройден! Награда за первое завершение уже получена.';void openModal('missionResult');}
for(let i=0;i<MISSIONS.length;i++)$('musicMission'+i).onclick=()=>launchMusicMission(MISSIONS[i].id);
$('retryMusicMission').onclick=()=>launchMusicMission(journey.missions.active?.id,'missionResult');
$('closeMusicResult').onclick=async()=>{journey.missions.cancel();save();await closeModal('missionResult');updateHUD();};
$('vehicleCourseStart').onclick=async()=>{if(flow.screen!=='roam'||flow.loading)return;if(!journey.startVehicleCourse()){toast('Сядь в машину или на мотоцикл и заверши текущее испытание.');return;}sideGoal=null;resetInput();save();await closeModal('journal');journeyEvents();updateHUD();};$('vehicleCourseReplay').onclick=async()=>{if(!journey.startVehicleCourse())return;resetInput();save();await closeModal('vehicleCourseResult');journeyEvents();updateHUD();};$('vehicleCourseExplore').onclick=async()=>{save();await closeModal('vehicleCourseResult');updateHUD();};$('crewRouteStart').onclick=async()=>{if(flow.screen!=='roam'||flow.loading)return;if(!journey.startCrewRoute()){toast('Сначала заверши другое испытание.');return;}sideGoal=null;save();await closeModal('journal');journeyEvents();updateHUD();};$('crewRouteCancel').onclick=async()=>{journey.crew.cancel();save();await closeModal('journal');updateHUD();};$('artifactMissionStart').onclick=async()=>{if(flow.screen!=='roam'||flow.loading)return;if(!journey.artifactQuest.start()){toast('Заверши текущее испытание и выйди из машины.');return;}sideGoal=null;resetInput();save();await closeModal('journal');journeyEvents();updateHUD();};$('artifactReplay').onclick=async()=>{if(!journey.artifactQuest.start())return;resetInput();save();await closeModal('artifactResult');journeyEvents();updateHUD();};$('artifactExplore').onclick=async()=>{save();await closeModal('artifactResult');updateHUD();};$('cancelMusicMission').onclick=async()=>{journey.missions.cancel();save();await closeModal('journal');updateHUD();};
$('missionRecover').onclick=()=>{if(flow.screen!=='roam'||flow.paused||flow.loading)return;if(journey.story.running)journey.story.recover();else journey.missions.recover();journeyEvents();};

function updateStyleHUD(){const st=journey.style,gr=journey.grind;$('skateTrick').disabled=gr.active?gr.active.switchCooldown>0:!!st.queued||(!!st.flight?.locked&&st.selected!=='manual')||!!journey.vehicle?.bail;$('skateTrick').setAttribute('aria-label',gr.active?'Сменить скольжение':'Выполнить выбранный трюк');const visible=flow.screen==='roam'&&journey.skating;$('styleHud').classList.toggle('hidden',!visible);$('styleTotal').textContent='Style '+st.total;$('styleCombo').textContent='×'+st.multiplier;$('stylePending').textContent=st.manual.active?'Manual · баланс '+Math.round(st.manual.active.balance*100)+'% · ← →':st.manual.armed?'Manual подготовлен':gr.active?gr.active.kind+' · баланс '+Math.round(gr.active.balance*100)+'% · ← →':gr.pending?gr.pending.kind+' · приземлись':st.pending?'+'+st.pending+' в полёте':'';$('styleBest').textContent='Рекорд '+st.best;$('trickNotice').classList.toggle('hidden',!visible||st.noticeTime<=0);$('trickNotice').textContent=st.notice;}
function trickAction(id){if(flow.screen!=='roam'||flow.paused||flow.loading||!journey.skating)return;if(id)journey.style.select(id);journey.trick(id);journeyEvents();updateStyleHUD();}
sound.onTrackEnded=()=>{if(flow.screen==='roam'&&!flow.paused&&!musicLoading)void nextMusic();};
bindImmediatePress($('skateTrick'),()=>trickAction());$('trickChoice').value=journey.style.selected;$('trickChoice').onchange=e=>{journey.style.select(e.target.value);e.target.blur?.();save();};


function updateActionHUD(action=interactionAt()){
 $('controlsOpen').textContent=TOUCH_LAYOUT()?'Действия':'?';$('controlsOpen').setAttribute('aria-label',TOUCH_LAYOUT()?'Действия и задания касанием':'Все команды и управление');
 const command=interactionCommand(action),context=action&&!['board','exit'].includes(command);
 $('interact').classList.toggle('hidden',!context);$('interact').disabled=!context;
 $('interact').classList.toggle('ready',!!context);
 if(context){$('interact').innerHTML=`<b>${action.label}</b><small>${COMMAND_LABELS[command]||''}</small>`;$('interact').setAttribute('aria-label',action.label+(TOUCH_LAYOUT()?'':' · '+COMMAND_LABELS[command]));}
 $('skateGuide').classList.toggle('hidden',!journey.skating);$('stickHint').textContent=journey.vehicle?'ВВЕРХ — ГАЗ · ВНИЗ — ТОРМОЗ':'В ЛЮБУЮ СТОРОНУ — ИДТИ';$('joystick').setAttribute('aria-label',journey.vehicle?'Джойстик транспорта: вверх — газ, вниз — тормоз и задний ход, в стороны — поворот':'Джойстик: направление движения относительно камеры');$('boardButton').classList.toggle('hidden',!!journey.vehicle);$('boardButton').disabled=!!skills.race;
 $('exitButton').classList.toggle('hidden',!journey.vehicle);$('exitButton').textContent=journey.vehicle?.id==='metro'?(journey.vehicle.requestExit?'На следующей':TOUCH_LAYOUT()?'Выйти':'Выйти · X'):journey.vehicle?.dismount?(journey.vehicle.id==='plane'?'Посадка…':'Тормозим…'):(journey.skating?'Сойти':'Выйти')+(TOUCH_LAYOUT()?'':' · X');
 $('brakeButton').classList.toggle('hidden',!journey.vehicle||journey.vehicle.id==='metro');$('brakeButton').textContent=journey.vehicle?.id==='plane'?'СНИЖЕНИЕ':'ТОРМОЗ';$('brakeButton').setAttribute('aria-label',journey.vehicle?.id==='plane'?(TOUCH_LAYOUT()?'Снижение: удерживать':'Снижение и посадка · держать Ctrl'):(TOUCH_LAYOUT()?'Тормоз: удерживать':'Тормоз · держать Ctrl'));
 $('nitroButton').classList.toggle('hidden',!journey.vehicle||journey.skating||['plane','metro'].includes(journey.vehicle.id));$('nitroFill').style.width=(journey.vehicle?.nitro??60)+'%';$('nitroButton').classList.toggle('boosting',!!journey.vehicle?.boosting);$('nitroButton').setAttribute('aria-label',(TOUCH_LAYOUT()?'Нитро: удерживать, заряд ':'Нитро: держать Z, заряд ')+Math.round(journey.vehicle?.nitro??60)+' процентов');
 $('jump').classList.toggle('hidden',!!journey.vehicle&&!journey.skating&&journey.vehicle.id!=='plane');
 $('dashBurst').classList.toggle('hidden',!!journey.vehicle);
 $('super').classList.toggle('hidden',!!journey.vehicle&&!journey.artifactQuest.powerActive('strong'));
}
async function runCommand(command){
 if(flow.screen!=='roam'||flow.paused||flow.loading)return;
 if(command==='help')return openModal('controls');
 if(command==='map')return openMap();if(command==='journal')return journal();if(command==='music')return toggleMusic();
 if(command==='recover')return $('missionRecover').onclick();
 if(command==='board'){if(!journey.vehicle&&!skills.race){journey.mountSkate();journeyEvents();}return;}
 if(command==='exit'){if(journey.vehicle){journey.exitVehicle();journeyEvents();}return;}
 if(command==='power')return superAction();
 if(command==='dash'){if(!journey.vehicle)skills.dash();return;}
 if(['kickflip','spin180','spin360','heelflip','shoveit','varial','hardflip','inwardheel','shove360','manual','trick'].includes(command))return trickAction(command==='trick'?undefined:command);
 const action=interactionAt();
 if(command==='dance'){if(action?.type==='podiumBattle'&&journey.quest>=5&&journey.celebrated&&!journey.story.running)return celebrate();if(action&&['final','storyFinish'].includes(action.type))return interact();return danceAction();}
 if(command==='challenge'&&!journey.story.running&&journey.skateChallengeAvailable)return $('skateChallengeStart').onclick();
 if(command===interactionCommand(action))return interact();
 if(command==='metro')return toast('Подойди к значку М пешком или остановись на скейте. Во время испытания на время сначала заверши заезд.');
 if(command==='vehicle')return toast(journey.vehicle?'Сначала нажми «Выйти».':journey.artifactQuest.running||journey.missions.running?'Сначала заверши текущее испытание.':'Подойди к машине, мотоциклу или самолёту. Они отмечены на карте.');
 if(command==='train')return toast('Подойди к тренеру у школы «Заметь наш стиль» и выбери «Урок у тренера».');
 if(command==='battle')return toast(journey.vehicle&&!journey.skating?'Сначала нажми «Выйти».':journey.artifactQuest.running||journey.missions.running?'Сначала заверши текущее испытание.':'Подойди к танцполу, подиуму или команде района и нажми «Начать баттл».');
}
$('boardButton').onclick=()=>runCommand('board');$('exitButton').onclick=()=>runCommand('exit');$('dashBurst').onclick=()=>runCommand('dash');
$('controlsList').innerHTML=CONTROL_HELP.map(([key,label])=>`<div class="control-row"><kbd>${key}</kbd><span>${label}</span></div>`).join('');
$('controlsOpen').onclick=()=>TOUCH_LAYOUT()?openTouchActions():openModal('controls');$('pauseControls').onclick=()=>openModal('controls');$('homeControls').onclick=()=>openModal('controls');$('closeControls').onclick=()=>closeModal('controls');
$('brakeButton').onpointerdown=e=>{if(flow.screen!=='roam'||flow.paused||flow.loading||brakePointer!==null)return;e.preventDefault();brakePointer=e.pointerId;touch.brake=true;e.currentTarget?.setPointerCapture?.(e.pointerId);};
for(const type of['pointerup','pointercancel','lostpointercapture'])$('brakeButton').addEventListener(type,e=>{if(e.pointerId===brakePointer){brakePointer=null;touch.brake=false;}});

