$('mirrorReplay').onclick=()=>{if(flow.screen==='freestyle'&&!flow.paused){freestylePractice=false;freestyleGame.replay(sound.time());freestyleEvents();}};
$('mirrorPractice').onclick=()=>{if(flow.screen==='freestyle'&&!flow.paused&&freestyleGame.canSkip){freestylePractice=!freestylePractice;freestyleGame.stopPreview();$('freestyleFeedback').textContent=freestylePractice?'Выбери движение для замедленного разбора. В связку оно не добавится.':'Выбери движения и нажми «Исполнить связку».';}};

// Contact actions stay usable while the other thumb owns the joystick/camera.
for(const [id,command]of[['boardButton','board'],['exitButton','exit'],['dashBurst','dash'],['super','power'],['dance','dance']])bindImmediatePress($(id),()=>{if(['board','exit','dash','power','dance'].includes(command)){$('worldActions').dataset.expanded='false';$('worldActions').classList.remove('expanded');$('mobileMore').setAttribute('aria-expanded','false');}return runCommand(command);});
bindImmediatePress($('interact'),()=>{$('worldActions').dataset.expanded='false';$('worldActions').classList.remove('expanded');$('mobileMore').setAttribute('aria-expanded','false');return runCommand(interactionCommand(interactionAt()));});
bindImmediatePress($('mobileMore'),()=>{if(flow.screen!=='roam'||flow.paused)return;const actions=$('worldActions');actions.dataset.expanded=actions.dataset.expanded==='true'?'false':'true';actions.classList.toggle('expanded',actions.dataset.expanded==='true');$('mobileMore').setAttribute('aria-expanded',actions.dataset.expanded);});

$('nitroButton').onpointerdown=e=>{if(flow.screen!=='roam'||flow.paused||flow.loading||nitroPointer!==null)return;e.preventDefault();nitroPointer=e.pointerId;touch.nitro=true;e.currentTarget?.setPointerCapture?.(e.pointerId);};
for(const type of['pointerup','pointercancel','lostpointercapture'])$('nitroButton').addEventListener(type,e=>{if(e.pointerId===nitroPointer){nitroPointer=null;touch.nitro=false;}});

async function openTouchActions(){
 for(const [id,disabled]of [['board',!!journey.vehicle||!!skills.race],['exit',!journey.vehicle],['manual',!journey.skating],['dash',!!journey.vehicle],['power',$('super').disabled],['recover',!journey.story.running&&!journey.missions.running]])$('touchCmd-'+id).disabled=disabled;
 const action=interactionAt();$('touchContext').textContent=action?.label||'Нет действия рядом';$('touchContext').disabled=!action;
 await openModal('touchActions');
}
$('closeTouchActions').onclick=()=>closeModal('touchActions');
$('touchContext').onclick=async()=>{primeAudio();await closeModal('touchActions');if(!flow.paused)await interact();};
for(const [command]of TOUCH_COMMANDS)$('touchCmd-'+command).onclick=async()=>{primeAudio();await closeModal('touchActions');await runCommand(command);};
